diff --git a/src/webhooks/backoff.ts b/src/webhooks/backoff.ts
new file mode 100644
index 0000000..7410a3b
--- /dev/null
+++ b/src/webhooks/backoff.ts
@@ -0,0 +1,8 @@
+/** The wait before the next attempt: the base delay, doubled after each failure. */
+export function computeBackoffMs(baseDelayMs: number, attempt: number): number {
+  return baseDelayMs * 2 ** (attempt - 1);
+}
+
+export function sleep(ms: number): Promise<void> {
+  return new Promise((resolve) => setTimeout(resolve, ms));
+}
