 }

 export function readWebhookConfig(
@@ -9,5 +11,7 @@ export function readWebhookConfig(
   return {
     endpointUrl: env.WEBHOOK_URL ?? "",
     timeoutMs: Number(env.WEBHOOK_TIMEOUT_MS ?? 5000),
