diff --git a/src/webhooks/deliver.ts b/src/webhooks/deliver.ts
index b367889..b97add7 100644
--- a/src/webhooks/deliver.ts
+++ b/src/webhooks/deliver.ts
@@ -1,3 +1,4 @@
+import { computeBackoffMs, sleep } from "./backoff";
 import type { WebhookConfig } from "./config";

 export interface Delivery {
@@ -5,14 +6,33 @@ export interface Delivery {
   readonly body: string;
 }

+async function postOnce(
+  config: WebhookConfig,
+  delivery: Delivery,
+): Promise<boolean> {
+  try {
+    const response = await fetch(config.endpointUrl, {
+      method: "POST",
+      body: delivery.body,
+      signal: AbortSignal.timeout(config.timeoutMs),
+    });
+    return response.ok;
+  } catch {
+    return false;
+  }
+}
+
 export async function deliver(
   config: WebhookConfig,
   delivery: Delivery,
 ): Promise<boolean> {
-  const response = await fetch(config.endpointUrl, {
-    method: "POST",
-    body: delivery.body,
-    signal: AbortSignal.timeout(config.timeoutMs),
-  });
-  return response.ok;
+  for (let attempt = 1; attempt <= config.maxAttempts; attempt++) {
+    if (await postOnce(config, delivery)) {
+      return true;
+    }
+    if (attempt < config.maxAttempts) {
+      await sleep(computeBackoffMs(config.baseDelayMs, attempt));
+    }
+  }
+  return false;
 }

